```kotlin
import java.util.*

class LruCache<K, V>(val capacity: Int, private val onEvict: (K, V) -> Unit = { _, _ -> }) {
    init {
        require(capacity >= 1) { "Capacity must be >= 1" }
    }

    private class Node<K, V>(var key: K, var value: V) {
        var prev: Node<K, V>? = null
        var next: Node<K, V>? = null
    }

    private val head = Node<K, V>(null as K, null as V)
    private val tail = Node<K, V>(null as K, null as V)
    private val map = HashMap<K, Node<K, V>>()

    init {
        head.next = tail
        tail.prev = head
    }

    private fun addFirst(node: Node<K, V>) {
        node.next = head.next
        node.prev = head
        head.next?.prev = node
        head.next = node
    }

    private fun removeNode(node: Node<K, V>) {
        val prev = node.prev
        val next = node.next
        prev?.next = next
        next?.prev = prev
        node.prev = null
        node.next = null
    }

    private fun moveToFirst(node: Node<K, V>) {
        removeNode(node)
        addFirst(node)
    }

    private fun removeLast(): Node<K, V>? {
        val node = tail.prev
        if (node != tail) {
            removeNode(node!!)
        }
        return node?.takeIf { it != tail }
    }

    operator fun get(key: K): V? {
        val node = map[key]
        if (node == null) return null

        moveToFirst(node)
        return node.value
    }

    operator fun set(key: K, value: V) {
        var existingNode = map[key]

        if (existingNode != null) {
            // Update existing node and move to front
            existingNode.value = value
            moveToFirst(existingNode)
        } else {
            // Create new node
            val newNode = Node(key, value)
            map[key] = newNode
            addFirst(newNode)

            // Check if we need to evict
            if (map.size > capacity) {
                val lastNode = removeLast()
                if (lastNode != null) {
                    map.remove(lastNode.key)
                    onEvict(lastNode.key, lastNode.value)
                }
            }
        }
    }

    fun remove(key: K): V? {
        val node = map.remove(key)
        if (node != null) {
            removeNode(node)
            return node.value
        }
        return null
    }

    val size: Int
        get() = map.size

    fun keys(): List<K> {
        val result = mutableListOf<K>()
        var current = head.next
        while (current != null && current != tail) {
            result.add(current.key)
            current = current.next
        }
        return result
    }

    operator fun contains(key: K): Boolean {
        return map.containsKey(key)
    }
}
