    if dt.hour not in hour_set:
        return False

    # Day matching (Vixie cron rules)
    dom_match = dt.day in dom_set
    dow_match = dt.weekday() + 1 in dow_set  # datetime.weekday() is Mon=0, Sun=6 → convert to Cron Sun=0, Sat=6

    # Actually, let's correct the conversion:
    # datetime weekday: Monday=0, Sunday=6
    # Cron: Sunday=0, Saturday=6
    cron_weekday = dt.weekday()
    # Convert: Monday=0 -> Cron Monday=1, ..., Sunday=6 -> Cron Sunday=0
    cron_weekday = (cron_weekday + 1) % 7

    dow_match = cron_weekday in dow_set

    # Vixie cron rule: if both DOM and DOW are restricted (not *), match if either matches.
    # Otherwise, both must match.
    dom_restricted = dom_set != set(range(1, 32))
    dow_restricted = dow_set != set(range(0, 7))

    if dom_restricted and dow_restricted:
        return dom_match or dow_match
    else:
        return dom_match and dow_match

def next_fire(expr: str, after: datetime) -> datetime:
    """Return the next datetime strictly after `after` that matches the cron expression."""
    # Split the expression into 5 fields
    fields = expr.split()

    if len(fields) != 5:
        raise ValueError(f"Invalid cron expression: expected 5 fields, got {len(fields)}")

    try:
        minute_set = parse_field(fields[0], 0)
        hour_set = parse_field(fields[1], 1)
        dom_set = parse_field(fields[2], 2)
        month_set = parse_field(fields[3], 3)
        dow_set = parse_field(fields[4], 4)
    except ValueError:
        raise

    # Validate sets are not empty
    if not minute_set or not hour_set or not dom_set or not month_set or not dow_set:
        raise ValueError("Empty field in cron expression")

    # Start from the next minute after `after`
    dt = after.replace(second=0, microsecond=0) + timedelta(minutes=1)

    # Maximum search period: 5 years
    max_dt = after.replace(second=0, microsecond=0) + timedelta(days=365*5 + 2)  # Add 2 for leap years

    # Use a loop to find the matching datetime
    iterations = 0
    max_iterations = 1000000  # Prevent infinite loops

    while dt < max_dt and iterations < max_iterations:
        iterations += 1

        # Check month
        if dt.month not in month_set:
            # Find next month that matches
            current_month = dt.month
            next_month = None
            for m in sorted(month_set):
                if m > current_month:
                    next_month = m
                    break

            if next_month is None:
                # Next year
                dt = datetime(dt.year + 1, min(month_set), 1, 0, 0)
                continue
            else:
                dt = datetime(dt.year, next_month, 1, 0, 0)
            continue

        # Day matching logic for Vixie cron
        dom_restricted = dom_set != set(range(1, 32))
        dow_restricted = dow_set != set(range(0, 7))

        # Convert datetime weekday to cron format (Sunday=0)
        cron_weekday = (dt.weekday() + 1) % 7

        dom_match = dt.day in dom_set
        dow_match = cron_weekday in dow_set

        if dom_restricted and dow_restricted:
            # Either DOM or DOW must match
            if not (dom_match or dow_match):
                # Move to next day
                dt = dt.replace(hour=0, minute=0) + timedelta(days=1)
                continue
        else:
            # Both DOM and DOW must match
            if not (dom_match and dow_match):
                # Move to next day
                dt = dt.replace(hour=0, minute=0) + timedelta(days=1)
                continue

        # Check hour
        if dt.hour not in hour_set:
            # Find next valid hour
            next_hour = None
            for h in sorted(hour_set):
                if h > dt.hour:
                    next_hour = h
                    break

            if next_hour is None:
                # Next day
                dt = dt.replace(hour=0, minute=0) + timedelta(days=1)
            else:
                dt = dt.replace(hour=next_hour, minute=0)
            continue

        # Check minute
        if dt.minute not in minute_set:
            # Find next valid minute
            next_minute = None
            for m in sorted(minute_set):
                if m > dt.minute:
                    next_minute = m
                    break

            if next_minute is None:
                # Next hour
                next_hour = None
                for h in sorted(hour_set):
                    if h > dt.hour:
                        next_hour = h
                        break

                if next_hour is None:
                    # Next day
                    dt = dt.replace(hour=0, minute=0) + timedelta(days=1)
                else:
                    dt = dt.replace(hour=next_hour, minute=0)
            else:
                dt = dt.replace(minute=next_minute)
            continue

        # If we reach here, we have a valid match
        return dt

    raise ValueError("No matching time found within 5 years")
