def parse_duration(s: str) -> int:
    """Parse a human-readable duration string into seconds."""
    if not s or not s.strip():
        raise ValueError("Empty input")

    s = s.strip()
    if not s:
        raise ValueError("Empty input")

    units = {'d': 86400, 'h': 3600, 'm': 60, 's': 1}
    unit_order = ['d', 'h', 'm', 's']

    total_seconds = 0
    i = 0
    found_units = set()

    while i < len(s):
        # Skip spaces
        if s[i] == ' ':
            i += 1
            continue

        # Parse integer
        j = i
        while j < len(s) and s[j].isdigit():
            j += 1

        if j == i:
            raise ValueError(f"Missing number at position {i}")

        value = int(s[i:j])
        i = j

        # Check for unit
        if i >= len(s):
            raise ValueError("Missing unit")

        unit = s[i].lower()
        if unit not in units:
            raise ValueError(f"Unknown unit '{s[i]}'")

        # Check for repeated units
        if unit in found_units:
            raise ValueError(f"Repeated unit '{unit}'")

        # Check unit order
        if unit not in unit_order:
            raise ValueError(f"Invalid unit '{unit}'")

        # Verify order constraint
        if found_units:
            last_unit = list(found_units)[-1]
            if unit_order.index(unit) <= unit_order.index(last_unit):
                raise ValueError(f"Wrong order: '{unit}' comes after '{last_unit}'")

        found_units.add(unit)
        i += 1

        total_seconds += value * units[unit]

    # Check if we consumed the entire string
    if i != len(s):
        raise ValueError(f"Invalid character at position {i}: '{s[i]}'")

    return total_seconds


def format_duration(seconds: int) -> str:
    """Format seconds as a human-readable duration string."""
    if seconds < 0:
        raise ValueError("Negative input")

    if seconds == 0:
        return "0s"

    units = [('d', 86400), ('h', 3600), ('m', 60), ('s', 1)]
    parts = []

    remaining = seconds
    for unit_name, unit_seconds in units:
        if remaining >= unit_seconds:
            count = remaining // unit_seconds
            parts.append(f"{count}{unit_name}")
            remaining %= unit_seconds

    return ''.join(parts)
