import re
from collections import OrderedDict


def flatten(obj, sep="."):
    """
    Flatten a nested structure (dict/list) into a flat dict with path keys.

    Args:
        obj: The object to flatten (must be a dict at the top level)
        sep: The separator to use for joining path segments

    Returns:
        A flat dictionary with path keys

    Raises:
        TypeError: If the top-level object is not a dict
        ValueError: If dict keys contain the separator
    """
    if not isinstance(obj, dict):
        raise TypeError("Top-level object must be a dict")

    result = OrderedDict()

    def _flatten(current, path_parts):
        # If current is a dict
        if isinstance(current, dict):
            # If empty dict, keep it as a leaf value
            if not current:
                if path_parts:
                    result[sep.join(path_parts)] = current
                return

            for key, value in current.items():
                # Check key is a string and doesn't contain sep
                if not isinstance(key, str):
                    raise ValueError("Dict keys must be strings")
                if sep in key:
                    raise ValueError(f"Dict key '{key}' contains separator '{sep}'")

                # Append key to path and continue flattening
                new_path = path_parts + [key]
                _flatten(value, new_path)

        # If current is a list
        elif isinstance(current, list):
            # If empty list, keep it as a leaf value
            if not current:
                if path_parts:
                    result[sep.join(path_parts)] = current
                return

            for i, item in enumerate(current):
                # Append index as string to path and continue flattening
                new_path = path_parts + [str(i)]
                _flatten(item, new_path)

        # If current is any other value (leaf)
        else:
            if path_parts:
                result[sep.join(path_parts)] = current

    _flatten(obj, [])
    return dict(result)


def unflatten(flat, sep="."):
    """
    Unflatten a flat dict with path keys into a nested structure (dict/list).

    Args:
        flat: The flat dictionary to unflatten
        sep: The separator used in the path keys

    Returns:
        A nested structure (dict with lists/dicts as appropriate)

    Raises:
        ValueError: If path segments are invalid or there are conflicts
    """
    if not isinstance(flat, dict):
        raise TypeError("Input must be a dict")

    # Helper to check if string represents a non-negative integer without leading zeros
    def is_valid_index(s):
        # Must be non-negative integer without leading zeros
        # "0" is valid, but "00", "01", etc. are not
        return bool(re.match(r'^(0|[1-9][0-9]*)$', s))

    # Helper to convert string index to int if valid
    def maybe_index(s):
        if is_valid_index(s):
            return int(s)
        return s

    # First, process all keys and build a tree structure
    # We'll use a recursive structure with dicts for keys and lists for indices
    result_tree = {}

    for path, value in flat.items():
        # Skip empty path
        if not path:
            if "" in result_tree:
                raise ValueError(f"Conflicting keys: empty key appears multiple times")
            result_tree[""] = value
            continue

        # Split the path into segments
        segments = path.split(sep)

        # Process each segment
        current = result_tree
        for i, segment in enumerate(segments):
            # Convert segment to appropriate type (int if valid index, else string)
            key = maybe_index(segment)

            # If this is the last segment, set the value
            if i == len(segments) - 1:
                # Check for conflicts
                if key in current:
                    # Different values mean conflict
                    if current[key] != value:
                        raise ValueError(f"Conflicting keys: {path} conflicts with existing key")
                else:
                    current[key] = value
            else:
                # Not the last segment, need to create intermediate structure

                # If key already exists, check if it's compatible
                if key in current:
                    # If it's a value (not dict/list), conflict
                    if not isinstance(current[key], (dict, list)):
                        raise ValueError(f"Conflicting keys: {path} conflicts with existing key")
                    # Otherwise continue with existing structure
                    current = current[key]
                else:
                    # Need to create intermediate structure
                    # Determine if next segment should be dict or list
                    next_segment = segments[i+1]
                    next_key = maybe_index(next_segment)

                    # If next key is an integer (index), create a list; otherwise create a dict
                    if isinstance(next_key, int):
                        # Create a list
                        # But we need to be careful: if next_key is 0, we need a list of at least size 1
                        # We'll create a list and set the appropriate index later
                        new_list = [None] * (next_key + 1) if next_key >= 0 else []
                        current[key] = new_list
                        current = new_list
                    else:
                        # Create a dict
                        new_dict = {}
                        current[key] = new_dict
                        current = new_dict

    # Now process the result to handle lists properly
    def finalize(obj):
        if isinstance(obj, dict):
            # Check if all keys are integers
            if all(isinstance(k, int) for k in obj.keys()):
                # It should be a list
                if not obj:
                    return []

                max_index = max(obj.keys())
                if max_index < 0:
                    raise ValueError("Negative indices not allowed")

                # Check if indices form a dense range 0..n-1
                expected_indices = set(range(len(obj)))
                actual_indices = set(obj.keys())
                if actual_indices != expected_indices:
                    raise ValueError(f"List indices must be exactly 0..n-1, got {sorted(actual_indices)}")

                # Create the list in order
                result_list = [None] * len(obj)
                for idx, val in obj.items():
                    result_list[idx] = finalize(val)
                return result_list
            else:
                # It's a dict
                result_dict = {}
                for k, v in obj.items():
                    # Convert int keys to strings if needed for dict keys
                    final_key = str(k) if isinstance(k, int) else k
                    result_dict[final_key] = finalize(v)
                return result_dict
        else:
            return obj

    return finalize(result_tree)
