def unflatten(flat, sep="."):
    """
    Unflatten a flat dict with path keys into a nested structure (dict/list).

    Args:
        flat: The flat dictionary to unflatten
        sep: The separator used in the path keys

    Returns:
        A nested structure (dict with lists/dicts as appropriate)

    Raises:
        ValueError: If path segments are invalid or there are conflicts
    """
    if not isinstance(flat, dict):
        raise TypeError("Input must be a dict")

    # Helper to check if string represents a non-negative integer without leading zeros
    def is_valid_index(s):
        # Must be non-negative integer without leading zeros
        # "0" is valid, but "00", "01", etc. are not
        return bool(re.match(r'^(0|[1-9][0-9]*)$', s))

    # First, collect all paths and their values
    paths = {}
    for path, value in flat.items():
        segments = path.split(sep)
        paths[path] = (segments, value)

    # Build the nested structure step by step
    root = {}

    for path, (segments, value) in paths.items():
        current = root
        for i, segment in enumerate(segments):
            # Determine if this segment should be treated as an index
            is_index = is_valid_index(segment)
            index = int(segment) if is_index else None

            if i == len(segments) - 1:
                # This is the final segment - set the value
                if is_index:
                    # Expand list if necessary
                    while len(current) <= index:
                        current.append(None)
                    if current[index] is not None and current[index] != value:
                        raise ValueError(f"Conflicting keys: {path} conflicts with existing key")
                    current[index] = value
                else:
                    if segment in current:
                        if current[segment] != value:
                            raise ValueError(f"Conflicting keys: {path} conflicts with existing key")
                    current[segment] = value
            else:
                # Not the final segment, need to create intermediate structure
                next_segment = segments[i + 1]
                next_is_index = is_valid_index(next_segment)

                if is_index:
                    # We're in a list; need to create either a list or dict for next level
                    while len(current) <= index:
                        current.append(None)

                    if current[index] is None:
                        # Decide based on next segment: list if next is index, dict otherwise
                        if next_is_index:
                            current[index] = []
                        else:
                            current[index] = {}
                    elif not isinstance(current[index], (list if next_is_index else dict)):
                        # Type conflict
                        if isinstance(current[index], list) and next_is_index:
                            pass  # OK
                        elif isinstance(current[index], dict) and not next_is_index:
                            pass  # OK
                        else:
                            raise ValueError(f"Type conflict for key {path}")

                    current = current[index]
                else:
                    # We're in a dict; need to create either a list or dict for next level
                    if segment not in current:
                        # Decide based on next segment: list if next is index, dict otherwise
                        if next_is_index:
                            current[segment] = []
                        else:
                            current[segment] = {}
                    elif not isinstance(current[segment], (list if next_is_index else dict)):
                        # Type conflict
                        if isinstance(current[segment], list) and next_is_index:
                            pass  # OK
                        elif isinstance(current[segment], dict) and not next_is_index:
                            pass  # OK
                        else:
                            raise ValueError(f"Type conflict for key {path}")

                    current = current[segment]

    # Now ensure list indices are dense (0..n-1) and convert dict-based lists to real lists
    def finalize(obj):
        if isinstance(obj, dict):
            # Check if all keys are string representations of integers 0..n-1
            # and in order to determine if it should be a list
            try:
                # Get all keys that are valid indices
                indices = []
                for k in obj:
                    if is_valid_index(str(k)):
                        indices.append(int(k))

                # If we found indices and they form a complete sequence from 0 to n-1
                if indices and sorted(indices) == list(range(len(indices))):
                    # Convert to list
                    result_list = [None] * len(indices)
                    for i in indices:
                        result_list[i] = finalize(obj[str(i)])
                    return result_list
                else:
                    # Keep as dict
                    result_dict = {}
                    for k, v in obj.items():
                        # Don't convert index keys back to ints
                        result_dict[k] = finalize(v)
                    return result_dict
            except:
                # If any error in conversion, treat as dict
                result_dict = {}
                for k, v in obj.items():
                    result_dict[k] = finalize(v)
                return result_dict
        elif isinstance(obj, list):
            # Process each element
            return [finalize(item) for item in obj]
        else:
            return obj

    return finalize(root)
