from typing import Union
import re

class Token:
    def __init__(self, type_, value=None):
        self.type = type_
        self.value = value

    def __repr__(self):
        return f"Token({self.type}, {self.value!r})"

def tokenize(expr: str):
    tokens = []
    i = 0
    while i < len(expr):
        c = expr[i]

        # Skip whitespace
        if c.isspace():
            i += 1
            continue

        # Numbers (integers and floats)
        if c.isdigit() or (c == '.' and i + 1 < len(expr) and expr[i+1].isdigit()):
            start = i
            has_dot = c == '.'
            i += 1
            while i < len(expr):
                if expr[i].isdigit():
                    i += 1
                elif expr[i] == '.' and not has_dot:
                    has_dot = True
                    i += 1
                else:
                    break

            token_str = expr[start:i]
            if '.' in token_str:
                tokens.append(Token('NUMBER', float(token_str)))
            else:
                tokens.append(Token('NUMBER', int(token_str)))
            continue

        # Identifiers
        if c.isalpha() or c == '_':
            start = i
            i += 1
            while i < len(expr) and (expr[i].isalnum() or expr[i] == '_'):
                i += 1
            token_str = expr[start:i]
            if token_str in ('true', 'false'):
                tokens.append(Token('BOOL', token_str == 'true'))
            else:
                tokens.append(Token('IDENT', token_str))
            continue

        # Two-character operators
        if c == '=' and i + 1 < len(expr) and expr[i+1] == '=':
            tokens.append(Token('EQ'))
            i += 2
            continue
        if c == '!' and i + 1 < len(expr) and expr[i+1] == '=':
            tokens.append(Token('NEQ'))
            i += 2
            continue
        if c == '<' and i + 1 < len(expr) and expr[i+1] == '=':
            tokens.append(Token('LEQ'))
            i += 2
            continue
        if c == '>' and i + 1 < len(expr) and expr[i+1] == '=':
            tokens.append(Token('GEQ'))
            i += 2
            continue
        if c == '&' and i + 1 < len(expr) and expr[i+1] == '&':
            tokens.append(Token('AND'))
            i += 2
            continue
        if c == '|' and i + 1 < len(expr) and expr[i+1] == '|':
            tokens.append(Token('OR'))
            i += 2
            continue

        # Single-character operators
        if c == '?' or c == ':' or c == '(' or c == ')' or c == '!' or c == '+' or c == '-' or c == '*' or c == '/' or c == '%' or c == '^' or c == '<' or c == '>' or c == '=':
            # Handle lone =, &, | as errors
            if c == '=' or c == '&' or c == '|':
                raise SyntaxError(f"Lone '{c}' found")
            tokens.append(Token(c))
            i += 1
            continue

        raise SyntaxError(f"Unknown character: '{c}'")

    return tokens

class Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def current(self):
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def peek(self):
        if self.pos + 1 < len(self.tokens):
            return self.tokens[self.pos + 1]
        return None

    def advance(self):
        self.pos += 1

    def match(self, *types):
        if self.current() and self.current().type in types:
            return True
        return False

    def expect(self, token_type):
        if self.current() and self.current().type == token_type:
            token = self.current()
            self.advance()
            return token
        raise SyntaxError(f"Expected {token_type}, got {self.current()}")

    def parse(self):
        if not self.tokens:
            raise SyntaxError("Empty expression")

        result = self.parse_conditional()

        if self.current():
            raise SyntaxError(f"Unexpected token '{self.current().type}'")

        return result

    def parse_conditional(self):
        expr = self.parse_or()

        if self.current() and self.current().type == '?':
            self.advance()  # consume '?'
            true_expr = self.parse_conditional()

            if not self.current() or self.current().type != ':':
                raise SyntaxError("Expected ':' after '?'")

            self.advance()  # consume ':'
            false_expr = self.parse_conditional()

            return ('conditional', expr, true_expr, false_expr)

        return expr

    def parse_or(self):
        left = self.parse_and()

        while self.current() and self.current().type == 'OR':
            self.advance()  # consume '||'
            right = self.parse_and()
            left = ('or', left, right)

        return left

    def parse_and(self):
        left = self.parse_comparison()

        while self.current() and self.current().type == 'AND':
            self.advance()  # consume '&&'
            right = self.parse_comparison()
            left = ('and', left, right)

        return left

    def parse_comparison(self):
        left = self.parse_additive()

        if self.current() and self.current().type in ('EQ', 'NEQ', 'LT', 'LEQ', 'GT', 'GEQ'):
            op = self.current().type
            self.advance()
            right = self.parse_additive()

            # Non-associative: check if right is comparison
            if isinstance(right, tuple) and right[0] in ('eq', 'neq', 'lt', 'leq', 'gt', 'geq'):
                raise SyntaxError("Chained comparisons are not allowed")

            if op == 'EQ':
                return ('eq', left, right)
            elif op == 'NEQ':
                return ('neq', left, right)
            elif op == 'LT':
                return ('lt', left, right)
            elif op == 'LEQ':
                return ('leq', left, right)
            elif op == 'GT':
                return ('gt', left, right)
            elif op == 'GEQ':
                return ('geq', left, right)

        return left

    def parse_additive(self):
        left = self.parse_multiplicative()

        while self.current() and self.current().type in ('PLUS', 'MINUS'):
            op = self.current().type
            self.advance()
            right = self.parse_multiplicative()

            if op == 'PLUS':
                left = ('add', left, right)
            else:  # MINUS
                left = ('sub', left, right)

        return left

    def parse_multiplicative(self):
        left = self.parse_unary()

        while self.current() and self.current().type in ('STAR', 'SLASH', 'MOD'):
            op = self.current().type
            self.advance()
            right = self.parse_unary()

            if op == 'STAR':
