    # Count occurrences of each character
    start_count = 0
    end_count = 0
    letter_counts = defaultdict(int)

    for row in grid:
        for cell in row:
            if cell == 'S':
                start_count += 1
            elif cell == 'E':
                end_count += 1
            elif cell in string.ascii_lowercase:
                letter_counts[cell] += 1
            elif cell not in '.#123456789':
                raise ValueError(f"Unknown character '{cell}' in grid")

    # Check exactly one S and one E
    if start_count != 1:
        raise ValueError(f"Expected exactly one 'S', found {start_count}")
    if end_count != 1:
        raise ValueError(f"Expected exactly one 'E', found {end_count}")

    # Check letters appear exactly 0 or 2 times
    for letter, count in letter_counts.items():
        if count != 2:
            raise ValueError(f"Letter '{letter}' appears {count} times (expected 0 or 2)")

    # Find positions
    start_pos = None
    end_pos = None
    teleport_pads = defaultdict(list)

    for r in range(n_rows):
        for c in range(n_cols):
            cell = grid[r][c]
            if cell == 'S':
                start_pos = (r, c)
            elif cell == 'E':
                end_pos = (r, c)
            elif cell in string.ascii_lowercase:
                teleport_pads[cell].append((r, c))

    # Map teleport pads to their destination
    teleport_map = {}
    for letter, positions in teleport_pads.items():
        if len(positions) == 2:
            p1, p2 = positions
            teleport_map[p1] = p2
            teleport_map[p2] = p1

    # Direction order: D, L, R, T, U (for lexicographically smallest)
    # But for normal moves, we need D, L, R, U
    # And T is teleport move which is special
    directions = [
        ('D', 1, 0),
        ('L', 0, -1),
        ('R', 0, 1),
        ('U', -1, 0)
    ]

    # Cost function for a cell
    def cell_cost(cell):
        if cell == 'S' or cell == 'E' or cell == '.' or cell in string.ascii_lowercase:
            return 1
        elif cell in '123456789':
            return int(cell)
        else:
            return 0  # Should not happen due to validation

    # Dijkstra with priority queue: (cost, moves_string, row, col)
    # To ensure lexicographically smallest, we need to compare paths carefully
    # Since moves_string is built in order, and we process in order of increasing cost,
    # then for same cost, lexicographically smallest string comes first

    # Initialize
    start_r, start_c = start_pos
    # Priority queue: (cost, moves, r, c)
    pq = [(1, '', start_r, start_c)]  # Start cell costs 1
    visited = {}  # (r, c) -> (cost, moves)

    while pq:
        cost, moves, r, c = heapq.heappop(pq)

        # Check if we reached the end
        if (r, c) == end_pos:
            return (cost, moves)

        # Skip if we've found a better way to this cell
        if (r, c) in visited:
            prev_cost, prev_moves = visited[(r, c)]
            if prev_cost < cost or (prev_cost == cost and prev_moves <= moves):
                continue

        # Mark visited
        visited[(r, c)] = (cost, moves)

        # Generate all possible next moves
        next_states = []

        # Normal moves (D, L, R, U)
        for move_char, dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < n_rows and 0 <= nc < n_cols:
                cell = grid[nr][nc]
                if cell != '#':
                    next_cost = cost + cell_cost(cell)
                    next_moves = moves + move_char
                    next_states.append((next_cost, next_moves, nr, nc))

        # Teleport move (T)
        if (r, c) in teleport_map:
            tr, tc = teleport_map[(r, c)]
            teleport_cost = cost + 2
            teleport_moves = moves + 'T'
            next_states.append((teleport_cost, teleport_moves, tr, tc))

        # Add valid next states to the priority queue
        for next_cost, next_moves, nr, nc in next_states:
            # Check if we have a better path to (nr, nc)
            if (nr, nc) not in visited or visited[(nr, nc)][0] > next_cost or \
               (visited[(nr, nc)][0] == next_cost and visited[(nr, nc)][1] > next_moves):
                heapq.heappush(pq, (next_cost, next_moves, nr, nc))

    # If we exit the loop, E is unreachable
    return None
