    """
    Parse a comparator like ">=1.2.3" or "~1.2.3" or "^1.2.3" or "1.2.3" into
    (operator, version). Operators can be: '<', '<=', '>', '>=', '=', '', '~', '^'.
    Returns (op, version).
    """
    comparator_str = comparator_str.strip()

    if not comparator_str:
        raise ValueError("Empty comparator")

