    if comparator_str.startswith(('>=', '<=', '>', '<', '=', '~', '^')):
        if comparator_str.startswith('~'):
            # Tilde operator: ~1.2.3 -> >=1.2.3 <1.3.0
            op = '~'
            version_part = comparator_str[1:].strip()
        elif comparator_str.startswith('^'):
            # Caret operator: ^1.2.3 -> >=1.2.3 <2.0.0
            op = '^'
            version_part = comparator_str[1:].strip()
        elif comparator_str.startswith('>='):
            op = '>='
            version_part = comparator_str[2:].strip()
        elif comparator_str.startswith('<='):
            op = '<='
            version_part = comparator_str[2:].strip()
        elif comparator_str.startswith('>'):
            op = '>'
            version_part = comparator_str[1:].strip()
        elif comparator_str.startswith('<'):
            op = '<'
            version_part = comparator_str[1:].strip()
        elif comparator_str.startswith('='):
            op = '='
            version_part = comparator_str[1:].strip()
        else:
