    # Pattern to match full SemVer string
    # MAJOR.MINOR.PATCH[-PRERELEASE][+BUILD]
    # where MAJOR, MINOR, PATCH are non-negative integers without leading zeros
    # PRERELEASE is dot-separated identifiers each matching [0-9A-Za-z-]+
    # BUILD is dot-separated identifiers each matching [0-9A-Za-z-]+
    pattern = r'^(\d+)\.(\d+)\.(\d+)(?:-((?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*)(?:\.(?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*))*))?(?:\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?$'
    match = re.match(pattern, v)

    if not match:
        raise ValueError(f"Invalid version string: {v}")

    major, minor, patch, prerelease_str, build_str = match.groups()

    major = int(major)
    minor = int(minor)
    patch = int(patch)

    prerelease = []
    if prerelease_str:
        for identifier in prerelease_str.split('.'):
            # Try to parse as integer first
            if re.fullmatch(r'\d+', identifier):
                # Check for leading zeros
                if len(identifier) > 1 and identifier.startswith('0'):
                    raise ValueError(f"Invalid numeric prerelease identifier: {identifier}")
                prerelease.append(int(identifier))
            else:
                prerelease.append(identifier)

    build = build_str or ""

    return Version(major, minor, patch, prerelease, build)


def parse_partial_version(version_str: str) -> Tuple[int, int, int, bool, bool, bool]:
