                        if ver.patch != 0:
                            upper = Version(ver.major, ver.minor, ver.patch + 1, [], "")
                        elif ver.minor != 0:
                            upper = Version(ver.major, ver.minor + 1, 0, [], "")
                        else:
                            upper = Version(ver.major + 1, 0, 0, [], "")
                        set_comparators.append(('<', upper))
                elif op == '^':
                    # Convert caret to a range
                    set_comparators.append(('>=', ver))
                    # For caret, determine the upper bound
                    if ver.prerelease:
                        # For prerelease targets, ^X means exact match
                        set_comparators.append(('=', ver))
                    else:
                        # Determine next version to exclude
                        if ver.major != 0:
                            upper = Version(ver.major + 1, 0, 0, [], "")
                        elif ver.minor != 0:
                            upper = Version(ver.major, ver.minor + 1, 0, [], "")
                        else:
                            upper = Version(ver.major, ver.minor, ver.patch + 1, [], "")
                        set_comparators.append(('<', upper))
                elif op == '=':
                    # =X means exact match
                    set_comparators.append(('>=', ver))
                    set_comparators.append(('<=', ver))
                else:
                    set_comparators.append((op, ver))

            result.append(set_comparators)

    return result


def satisfies(version: str, rng: str) -> bool:
    """
    Check if a version satisfies a range.
    """
    try:
        ver = parse(version)
    except ValueError:
        return False

    # Handle empty range (should be invalid but per test we need to handle it)
    if not rng or rng.strip() == '':
        raise ValueError("Empty range")

    try:
        ranges = parse_range(rng)
    except ValueError:
        raise ValueError(f"Invalid range: {rng}")

    # Check each OR set
    for or_set in ranges:
        # Check if all comparators in this set are satisfied
        all_satisfied = True
        for op, target in or_set:
            if op == '':
                # Empty operator means anything
                continue

            # Check for prerelease compatibility
            if ver.prerelease and not target.prerelease:
                # Prerelease versions only satisfy sets that have a prerelease target
                # with the same major.minor.patch and prerelease
                if not (target.major == ver.major and target.minor == ver.minor and target.patch == ver.patch):
                    all_satisfied = False
                    break
                # We need to check if there's a prerelease target in the set
                # For simplicity, skip unless there's a direct prerelease match
                # Actually, per npm spec, this version should not satisfy unless the target is prerelease
                all_satisfied = False
                break

            if op == '~':
                if not satisfies_tilde(ver, target):
                    all_satisfied = False
                    break
            elif op == '^':
                if not satisfies_caret(ver, target):
                    all_satisfied = False
                    break
            else:
                if not satisfies_version(ver, op, target):
                    all_satisfied = False
                    break

        if all_satisfied:
            return True

    return False


def max_satisfying(versions: List[str], rng: str) -> Optional[str]:
    """
    Return the version string that satisfies the range and is the highest.
    Return None if no version satisfies.
    """
    # Handle empty range
    if not rng or rng.strip() == '':
        raise ValueError("Empty range")

    # Parse all versions
    parsed_versions = []
    for v in versions:
        try:
            parsed_versions.append((parse(v), v))
        except ValueError:
            continue

    # Filter to those that satisfy
    satisfying = [(ver, orig) for ver, orig in parsed_versions if satisfies(orig, rng)]

    if not satisfying:
        return None

    # Sort by version (descending) and return the highest
    satisfying.sort(key=lambda x: x[0], reverse=True)
    return satisfying[0][1]
