def split_command(line: str, env: dict[str, str]) -> list[str]:
    """Parse a command line into a list of arguments, handling shell-like quoting and expansion."""
    result = []
    i = 0
    n = len(line)

    # Current word being built
    current_word = []
    current_parts = []  # For quoted parts that need joining

    # State tracking
    in_single_quotes = False
    in_double_quotes = False
    in_word = False

    def flush_current_word():
        nonlocal current_word, in_word
        if current_word:
            # Process the word: handle expansions and joining
            processed = []
            for part in current_word:
                if isinstance(part, str):
                    # This is a literal string part
                    processed.append(part)
                else:
                    # This is an expansion result
                    expanded = part
                    if in_double_quotes:
                        # No field splitting inside double quotes
                        processed.append(expanded)
                    else:
                        # Field splitting outside quotes
                        if expanded:
                            parts = expanded.split()
                            processed.extend(parts)
            # Join all parts for this word
            final_word = ''.join(processed)
            if final_word or (not current_word):  # keep empty if it was originally empty quotes
                result.append(final_word)
            current_word = []
            in_word = False

    while i < n:
        c = line[i]

        if in_single_quotes:
            if c == "'":
                in_single_quotes = False
                i += 1
            else:
                current_word.append(c)
                i += 1
        elif in_double_quotes:
            if c == '"':
                in_double_quotes = False
                i += 1
            elif c == '\\':
                # Handle escapes in double quotes
                if i + 1 < n:
                    next_c = line[i + 1]
                    if next_c in '$"\\\n':
                        # Escaped characters: remove backslash, keep the char
                        current_word.append(next_c)
                        i += 2
                    else:
                        # Backslash stays as is (except for newline which is handled above)
                        current_word.append('\\')
                        i += 1
                else:
                    raise ValueError("trailing unescaped backslash")
            elif c == '$':
                # Variable expansion in double quotes
                i += 1
                if i < n:
                    if line[i] == '{':
                        # ${...} expansion
                        i += 1
                        var_name, i = parse_var_name(line, i, n)
                        if i >= n:
                            raise ValueError("unterminated ${")
                        # Check for default syntax
                        default = None
                        has_default = False
                        if i < n and line[i:i+2] == ':-':
                            has_default = True
                            i += 2
                            default, i = parse_default(line, i, n, env, False, True)
                        elif i < n and line[i] == '-':
                            has_default = True
                            i += 1
                            default, i = parse_default(line, i, n, env, False, True)

                        # Expect closing brace
                        if i >= n or line[i] != '}':
                            raise ValueError("unterminated ${")
                        i += 1

                        # Get variable value
