                in_single_quotes = True
                i += 1
            elif c == '"':
                # Start double quotes
                in_double_quotes = True
                i += 1
            elif c == '\\':
                # Unquoted backslash
                if i + 1 < n:
                    if line[i + 1] == '\n':
