                else:
                    # End of line with $, treat as literal
                    current_word.append('$')
            else:
                # Regular character
                current_word.append(c)
                i += 1

    # Flush final word
    flush_current_word()

    return result

def parse_var_name(line: str, i: int, n: int) -> tuple[str, int]:
    """Parse variable name starting at i."""
    start = i
    while i < n and (line[i].isalnum() or line[i] == '_'):
        i += 1
    return line[start:i], i

def parse_default(line: str, i: int, n: int, env: dict[str, str], in_single: bool, in_double: bool) -> tuple[str, int]:
    """Parse default value for ${var:-default} or ${var-default}."""
    default_parts = []
    brace_depth = 1
    local_single = in_single
    local_double = in_double

    while i < n and brace_depth > 0:
        c = line[i]

        if local_single:
            if c == "'":
                local_single = False
                i += 1
            else:
                default_parts.append(c)
                i += 1
        elif local_double:
            if c == '"':
                local_double = False
                i += 1
            elif c == '\\':
                if i + 1 < n:
                    next_c = line[i + 1]
                    if next_c in '$"\\\n':
                        default_parts.append(next_c)
                        i += 2
                    else:
                        default_parts.append('\\')
                        i += 1
                else:
                    raise ValueError("trailing unescaped backslash")
            elif c == '$':
                # Handle $ in default
                i += 1
                if i < n:
                    if line[i] == '{':
                        default_parts.append('$')
                        i += 1
                        var_name, i = parse_var_name(line, i, n)
                        default_parts.append(var_name)
                        # Look for }
                        while i < n and line[i] != '}':
                            i += 1
                        if i < n:
                            default_parts.append('}')
                            i += 1
                    elif line[i].isalnum() or line[i] == '_':
                        default_parts.append('$')
                        var_name, i = parse_var_name(line, i, n)
                        default_parts.append(var_name)
                    else:
                        default_parts.append('$')
                        i -= 1
                else:
                    default_parts.append('$')
            else:
                default_parts.append(c)
                i += 1
        else:
            if c == '{':
                brace_depth += 1
                default_parts.append(c)
                i += 1
            elif c == '}':
                brace_depth -= 1
                if brace_depth > 0:
                    default_parts.append(c)
                i += 1
            elif c == "'":
                local_single = True
                i += 1
            elif c == '"':
                local_double = True
                i += 1
            else:
                default_parts.append(c)
                i += 1

    # Join parts and expand $ in default
    default_str = ''.join(default_parts)

    # Expand $ variables in default
    expanded = []
    j = 0
    while j < len(default_str):
        if default_str[j] == '$':
            if j + 1 < len(default_str) and default_str[j + 1] == '{':
                j += 2
                var_name, j = parse_var_name(default_str, j, len(default_str))
                if j < len(default_str) and default_str[j] == '}':
                    j += 1
                    value = env.get(var_name, "")
                    expanded.append(value)
                else:
                    expanded.append('$')
                    expanded.append(var_name)
            elif j + 1 < len(default_str) and (default_str[j + 1].isalnum() or default_str[j + 1] == '_'):
                j += 1
                var_name, j = parse_var_name(default_str, j, len(default_str))
                value = env.get(var_name, "")
                expanded.append(value)
            else:
                expanded.append('$')
                j += 1
        else:
            expanded.append(default_str[j])
            j += 1

    return ''.join(expanded), i

# Make it compatible with the test interface
def sp(line: str, env: dict) -> list:
    return split_command(line, env)

