from dataclasses import dataclass, fields, is_dataclass, MISSING
from typing import get_type_hints, Union, Optional, List, Dict, Tuple, Any, Literal, get_args, get_origin
import re


class LoadError(ValueError):
    def __init__(self, path: str, message: str):
        self.path = path
        super().__init__(f"{path}: {message}")


def load(cls, data: Any):
    """Build an instance of a (possibly nested) @dataclass type `cls` from JSON-like `data`."""
    hints = get_type_hints(cls)
    return _load_value(cls, data, "$", hints)


def _load_value(cls, data: Any, path: str, hints: dict = None) -> Any:
    """Load a value of type `cls` from `data`, with error path `path`."""
    # Handle None type
    if cls is type(None):
        if data is None:
            return None
        raise LoadError(path, f"expected None, got {type(data).__name__}")

    # Handle Literal[...]
    if get_origin(cls) is Literal:
        literals = get_args(cls)
        if data in literals and type(data) == type(literals[0]):
            return data
        raise LoadError(path, f"value must be one of {literals}, got {data!r}")

    # Handle Union/Optional
    origin = get_origin(cls)
    if origin is Union:
        args = get_args(cls)
        # Try each union member in order
        errors = []
        for arg in args:
            try:
                return _load_value(arg, data, path, hints)
            except LoadError as e:
                # Store the error but continue trying
                errors.append((arg, e))

        # If no union member loaded successfully, raise an error for the union
        raise LoadError(path, f"could not load as any of {cls}, last error was: {errors[-1][1]}")

    # Handle dataclasses
    if is_dataclass(cls):
        if not isinstance(data, dict):
            raise LoadError(path, f"expected dict for dataclass {cls.__name__}, got {type(data).__name__}")

        # Get the actual field annotations for this dataclass
        field_hints = hints if hints is not None else get_type_hints(cls)

        # Check for unknown keys and collect errors in order
        known_fields = {f.name for f in fields(cls)}
        for key in data:
            if key not in known_fields:
                raise LoadError(path + f".{key}", "unknown key")

        # Build the instance
        kwargs = {}
        for field in fields(cls):
            field_name = field.name
            field_path = path + f".{field_name}"

            if field_name not in data:
                # Missing key
                if field.default is not MISSING:
                    kwargs[field_name] = field.default
                elif field.default_factory is not MISSING:
                    kwargs[field_name] = field.default_factory()
                else:
                    raise LoadError(field_path, "missing required field")
                continue

            field_value = data[field_name]
            try:
                kwargs[field_name] = _load_value(field_hints[field_name], field_value, field_path, hints)
            except LoadError as e:
                # If the LoadError already has the right path, just re-raise
                raise e

        return cls(**kwargs)

    # Handle list[T]
    if origin is list:
        args = get_args(cls)
        if not args:
            raise LoadError(path, "list type missing argument")
        item_type = args[0]

        if not isinstance(data, list):
            raise LoadError(path, f"expected list, got {type(data).__name__}")

        result = []
        for i, item in enumerate(data):
            item_path = path + f"[{i}]"
            try:
                result.append(_load_value(item_type, item, item_path, hints))
            except LoadError as e:
                raise e
        return result

    # Handle tuple[T, ...] or tuple[A, B, ...]
    if origin is tuple:
        args = get_args(cls)
        if not args:
            raise LoadError(path, "tuple type missing arguments")

        if not isinstance(data, list):
            raise LoadError(path, f"expected list for tuple, got {type(data).__name__}")

        # Check if this is a variable-length tuple (tuple[T, ...]) or fixed-length tuple (tuple[A, B, ...])
        if len(args) == 2 and args[1] is Ellipsis:
            # Variable-length tuple: tuple[T, ...]
            item_type = args[0]
            result = []
            for i, item in enumerate(data):
                item_path = path + f"[{i}]"
                try:
                    result.append(_load_value(item_type, item, item_path, hints))
                except LoadError as e:
                    raise e
            return tuple(result)
        else:
            # Fixed-length tuple: tuple[A, B, C, ...]
            if len(data) != len(args):
                raise LoadError(path, f"expected tuple of length {len(args)}, got length {len(data)}")

            result = []
            for i, (arg, item) in enumerate(zip(args, data)):
                item_path = path + f"[{i}]"
                try:
                    result.append(_load_value(arg, item, item_path, hints))
                except LoadError as e:
                    raise e
            return tuple(result)

    # Handle dict[str, T]
    if origin is dict:
        args = get_args(cls)
        if len(args) < 2:
            raise LoadError(path, "dict type missing arguments")

        key_type, value_type = args[0], args[1]

        if not isinstance(data, dict):
            raise LoadError(path, f"expected dict, got {type(data).__name__}")

        result = {}
        for key, value in data.items():
            # For dict keys, only str is allowed in JSON
            if not isinstance(key, str):
                raise LoadError(path, f"dict keys must be strings, got {type(key).__name__}")

            key_path = path + f".{key}"
            try:
                result[key] = _load_value(value_type, value, key_path, hints)
            except LoadError as e:
                # For dict values, we don't need to change the path since it already includes the key
                raise e
        return result

    # Handle basic types
    # Bool must come before int because bool is subclass of int
    if cls is bool:
        if isinstance(data, bool):
            return data
        raise LoadError(path, f"expected bool, got {type(data).__name__}")

    if cls is int:
        if isinstance(data, bool):
            raise LoadError(path, f"expected int, got bool")
        if isinstance(data, int) and not isinstance(data, float):
            return data
        raise LoadError(path, f"expected int, got {type(data).__name__}")

    if cls is float:
        if isinstance(data, bool):
            raise LoadError(path, f"expected float, got bool")
        if isinstance(data, (int, float)):
            return float(data)
        raise LoadError(path, f"expected float, got {type(data).__name__}")

    if cls is str:
        if isinstance(data, str):
            return data
        raise LoadError(path, f"expected str, got {type(data).__name__}")

    # Fallback for other types
    raise LoadError(path, f"unsupported type {cls}")
