    FS = ""
    in_quote = 0
    field = ""
    n = 0
    col = ENVIRON["COL_IDX"]
    summary = ENVIRON["SUMMARY"]
    row = 0
    delim = ENVIRON["DELIM"]
}

function process_field() {
    if (row > 0 && n == col) {
        if (summary == 0) {
            # For non-summary, print field as is (newlines preserved)
            print field
        } else {
            # For summary mode, collect numeric values
            if (field != "" && field ~ /^[-+]?([0-9]+\.?[0-9]*|[0-9]*\.?[0-9]+)([eE][-+]?[0-9]+)?$/) {
                nums[++num_count] = field + 0
                if (num_count == 1 || field + 0 < min_val) min_val = field + 0
                if (num_count == 1 || field + 0 > max_val) max_val = field + 0
                sum_val += field + 0
            }
        }
    }
    field = ""
}

function end_row() {
    if (row > 0 && n < col) {
        # Fewer fields than header
        if (summary == 0) {
            print ""
        }
    }
    n = 0
}

{
    if (NR == 1) {
        # Parse header row
        for (i = 1; i <= length($0); i++) {
            c = substr($0, i, 1)
            if (in_quote) {
                if (c == "\"") {
                    if (i < length($0) && substr($0, i+1, 1) == "\"") {
                        header_field = header_field "\""
                        i++
                    } else {
                        in_quote = 0
                    }
                } else {
                    header_field = header_field c
                }
            } else {
                if (c == "\"") {
                    in_quote = 1
                } else if (c == delim) {
                    header_fields[++header_count] = header_field
                    header_field = ""
                } else {
                    header_field = header_field c
                }
            }
        }
        header_fields[++header_count] = header_field
        header_field = ""
        in_quote = 0
        row = 1
        next
    }

    # Parse data rows
    for (i = 1; i <= length($0); i++) {
        c = substr($0, i, 1)
        if (in_quote) {
            if (c == "\"") {
                if (i < length($0) && substr($0, i+1, 1) == "\"") {
                    field = field "\""
                    i++
                } else {
                    in_quote = 0
                }
            } else {
                field = field c
            }
        } else {
            if (c == "\"") {
                in_quote = 1
            } else if (c == delim) {
                n++
                process_field()
            } else {
                field = field c
            }
        }
    }

    # End of line processing
    if (in_quote) {
        # Still in quote, add newline to field
        field = field "\n"
    } else {
        n++
        process_field()
        end_row()
    }
}

END {
    if (in_quote) {
        print "Error: Unterminated quote at end of input" > "/dev/stderr"
        exit 4
    }

    if (summary == 1) {
        if (num_count == 0) {
            print "count=0"
        } else {
            printf "count=%d sum=%g min=%g max=%g\n", num_count, sum_val, min_val, max_val
        }
    }
}
ENDAWK
)

# Write awk script to file and run it
echo "$AWKSCRIPT" > "${TMPFILE}.script"

COL_IDX="$COL_IDX" SUMMARY="$SUMMARY" DELIM="$DELIM" awk -f "${TMPFILE}.script" "$TMPFILE"
AWK_EXIT=$?

if [[ $AWK_EXIT -eq 4 ]]; then
    exit 4
fi
