#!/bin/bash

# Check argument
if [[ $# -ne 1 ]]; then
    echo "Usage: $0 FILE" >&2
    exit 1
fi

FILE="$1"

# Check if file exists and is readable
if [[ ! -r "$FILE" ]]; then
    echo "$FILE: cannot read file" >&2
    exit 1
fi

# Process the dotenv file
awk '
BEGIN {
    # Initialize error flag
    error = 0
    line_count = 0
}

{
    line_count++
    line = $0

    # Remove leading/trailing whitespace for initial processing
    gsub(/^[ \t]+|[ \t]+$/, "", line)

    # Skip empty lines and comments
    if (line == "" || substr(line, 1, 1) == "#") {
        next
    }

    # Remove optional leading "export "
    if (substr(line, 1, 7) == "export ") {
        line = substr(line, 8)
    }

    # Check for KEY=VALUE pattern
    if (!match(line, /^[A-Za-z_][A-Za-z0-9_]*=/)) {
        print FILENAME ":" NR ": invalid line" > "/dev/stderr"
        error = 1
        exit 1
    }

    # Extract key and value
    eq_pos = index(line, "=")
    key = substr(line, 1, eq_pos - 1)
    value_part = substr(line, eq_pos + 1)

    # Process the value
    value = ""
    i = 1
    len = length(value_part)

    while (i <= len) {
        c = substr(value_part, i, 1)

        if (c == "'\''") {
            # Single quoted value
            i++
            start = i
            while (i <= len && substr(value_part, i, 1) != "'\''") {
                i++
            }
            # Extract the quoted content
            inner = substr(value_part, start, i - start)
            # Check that everything after closing quote is empty or comment
            if (i < len) {
                rest = substr(value_part, i + 1)
                # Only allow whitespace and comments
                gsub(/^[ \t]+/, "", rest)
                if (rest != "" && substr(rest, 1, 1) != "#") {
                    print FILENAME ":" NR ": invalid line" > "/dev/stderr"
                    error = 1
                    exit 1
                }
            }
            value = inner
            break
        } else if (c == "\"") {
            # Double quoted value
            i++
            while (i <= len) {
                c2 = substr(value_part, i, 1)
                if (c2 == "\\") {
                    i++
                    if (i <= len) {
                        c3 = substr(value_part, i, 1)
                        if (c3 == "n") {
                            value = value "\n"
                        } else if (c3 == "\"") {
                            value = value "\""
                        } else if (c3 == "\\") {
                            value = value "\\"
                        } else {
                            # Other escapes: keep as is
                            value = value "\\" c3
                        }
                        i++
                    }
                } else if (c2 == "\"") {
                    i++
                    # Check that everything after closing quote is empty or comment
                    if (i <= len) {
                        rest = substr(value_part, i)
                        gsub(/^[ \t]+/, "", rest)
                        if (rest != "" && substr(rest, 1, 1) != "#") {
                            print FILENAME ":" NR ": invalid line" > "/dev/stderr"
                            error = 1
                            exit 1
                        }
                    }
                    break
                } else {
                    value = value c2
                    i++
                }
            }
            break
        } else if (c == " " || c == "\t") {
            # Skip leading spaces
            i++
        } else {
            # Unquoted value - read until unquoted comment
            start = i
            while (i <= len) {
                c2 = substr(value_part, i, 1)
                if (c2 == " " || c2 == "\t") {
                    # Found whitespace, check for unquoted comment
                    j = i
                    # Skip all whitespace
                    while (j <= len && (substr(value_part, j, 1) == " " || substr(value_part, j, 1) == "\t")) {
                        j++
                    }
                    # Check if next char is # (comment)
                    if (j <= len && substr(value_part, j, 1) == "#") {
                        # This is the end of value
                        value = substr(value_part, start, i - start)
                        # Trim trailing spaces
                        gsub(/[ \t]+$/, "", value)
                        break
                    }
                    # Not a comment, skip whitespace and continue
                    i = j
                } else if (c2 == "#") {
                    # This is an unquoted comment
                    value = substr(value_part, start, i - start)
                    # Trim trailing spaces
                    gsub(/[ \t]+$/, "", value)
                    break
                } else {
                    i++
                }
            }
            # If we reached the end without a comment, take all
            if (i > len) {
                value = substr(value_part, start)
                gsub(/[ \t]+$/, "", value)
            }
            break
        }
    }

    # Store the key and value, later value overwrites earlier
    keys[key] = value
}

END {
    # If there was an error, exit with status 1
    if (error) {
        exit 1
    }

    # Process keys in order
    for (key in keys) {
        # Get the value
        val = keys[key]

        # Escape single quotes: replace ' with '"'"'
        gsub(/'\''/, "'\''\"'\''\"'\''", val)

        # Print export statement
        print "export " key "='\''" val "'\''"
    }
}
' "$FILE"

# Capture awk exit status
AWK_EXIT=$?

if [[ $AWK_EXIT -ne 0 ]]; then
    exit 1
fi
