#!/bin/bash

# Check argument
if [[ $# -ne 1 ]]; then
    echo "Usage: $0 FILE" >&2
    exit 1
fi

FILE="$1"

# Check if file exists and is readable
if [[ ! -r "$FILE" ]]; then
    echo "$FILE: cannot read file" >&2
    exit 1
fi

# Process the dotenv file
awk '
BEGIN {
    error = 0
}

{
    # Skip blank lines
    if ($0 ~ /^[[:space:]]*$/) next

    # Skip comment lines
    if ($0 ~ /^[[:space:]]*#/) next

    line = $0

    # Remove optional leading "export "
    if (line ~ /^export[[:space:]]/) {
        line = substr(line, 8)
        gsub(/^[[:space:]]+/, "", line)
    }

    # Extract key (must match pattern)
    if (!match(line, /^[A-Za-z_][A-Za-z0-9_]*/)) {
        print FILENAME ":" NR ": invalid line" > "/dev/stderr"
        error = 1
        exit 1
    }

    key = substr(line, RSTART, RLENGTH)
    rest = substr(line, RSTART + RLENGTH)

    # Must have "=" after key
    if (substr(rest, 1, 1) != "=") {
        print FILENAME ":" NR ": invalid line" > "/dev/stderr"
        error = 1
        exit 1
    }

    value_part = substr(rest, 2)

    # Process the value
    value = ""
    i = 1
    len = length(value_part)

    while (i <= len) {
        c = substr(value_part, i, 1)

        # Skip leading whitespace in unquoted values
        if (c == " " || c == "\t") {
            if (value == "") {
                i++
                continue
            }
        }

        # Start single-quoted value
        if (c == "'\''") {
            i++
            while (i <= len) {
                c2 = substr(value_part, i, 1)
                if (c2 == "'\''") {
                    i++
                    # Check anything after quote
                    if (i <= len) {
                        rest_after = substr(value_part, i)
                        gsub(/^[[:space:]]+/, "", rest_after)
                        if (rest_after != "" && substr(rest_after, 1, 1) != "#") {
                            print FILENAME ":" NR ": invalid line" > "/dev/stderr"
                            error = 1
                            exit 1
                        }
                    }
                    break
                } else {
                    value = value c2
                    i++
                }
            }
            break
        }

        # Start double-quoted value
        if (c == "\"") {
            i++
            while (i <= len) {
                c2 = substr(value_part, i, 1)
                if (c2 == "\\") {
                    i++
                    if (i <= len) {
                        c3 = substr(value_part, i, 1)
                        if (c3 == "n") {
                            value = value "\n"
                        } else if (c3 == "\"") {
                            value = value "\""
                        } else if (c3 == "\\") {
                            value = value "\\"
                        } else {
                            value = value "\\" c3
                        }
                        i++
                    }
                } else if (c2 == "\"") {
                    i++
                    # Check anything after quote
                    if (i <= len) {
                        rest_after = substr(value_part, i)
                        gsub(/^[[:space:]]+/, "", rest_after)
                        if (rest_after != "" && substr(rest_after, 1, 1) != "#") {
                            print FILENAME ":" NR ": invalid line" > "/dev/stderr"
                            error = 1
                            exit 1
                        }
                    }
                    break
                } else {
                    value = value c2
                    i++
                }
            }
            break
        }

        # Unquoted value
        start = i
        while (i <= len) {
            c2 = substr(value_part, i, 1)
            if (c2 == "#") {
                # Comment starts - trim trailing spaces
                value = substr(value_part, start, i - start)
                gsub(/[[:space:]]+$/, "", value)
                break
            }
            if (c2 == " " || c2 == "\t") {
                # Check if this space is followed by #
                j = i + 1
                while (j <= len && (substr(value_part, j, 1) == " " || substr(value_part, j, 1) == "\t")) {
                    j++
                }
                if (j <= len && substr(value_part, j, 1) == "#") {
                    value = substr(value_part, start, i - start)
                    gsub(/[[:space:]]+$/, "", value)
                    break
                }
                # Otherwise, just skip whitespace
                i++
            } else {
                i++
            }
        }
        # If we reached end, take all
        if (i > len && value == "") {
            value = substr(value_part, start)
            gsub(/[[:space:]]+$/, "", value)
        }
        break
    }

    # Store key-value pair (later value overwrites earlier)
    keys[key] = value
}

END {
    if (error) {
        exit 1
    }

    for (key in keys) {
        val = keys[key]

        # Escape single quotes: replace ' with '\'' 
        gsub(/'\''/, "'\''\"'\''\"'\''", val)

        print "export " key "='\''" val "'\''"
    }
}
' "$FILE"

exit $?
